UPDATE tbl_fixed_expense_candidate
SET avg_amount = #{candidate.avgAmount},
    cycle_days = #{candidate.cycleDays},
    detected_count = #{candidate.detectedCount},
    category_id = #{candidate.categoryId},
    next_expected_date = #{candidate.nextExpectedDate}
WHERE id = #{candidate.id}
  AND user_id = #{candidate.userId}
  AND is_excluded = 0
  AND status = 'ACTIVE'

UPDATE tbl_transaction t
SET candidate_id = #{candidateId}
WHERE 
  AND t.merchant_name_normalized = #{merchantNameNormalized}
